/**
 * Base64 encoded logos for use in image generation
 * These are embedded directly to avoid fetch issues and improve performance
 * Auto-generated - do not edit manually
 * All SVG logos are converted to PNG format for better compatibility
 */

export const LOGOS = {
  roboz: {
    png: ``,
    textPng: ``,
  },
  models: {
    'openai': ``,
    'claude': ``,
    'gemini': ``,
    'meta': ``,
    'deepseek': ``,
    'qwen': ``,
    'mistral': ``,
    'xai': ``,
    'cohere': ``,
    'perplexity': ``,
  },
} as const;

export function getRobozLogoBase64(): string {
  return LOGOS.roboz.png || LOGOS.roboz.textPng || '';
}

export function getModelLogoBase64(modelName: string | null): string {
  if (!modelName) return '';
  
  // Extract provider from model name (e.g., 'openai/gpt-5' -> 'openai')
  const provider = modelName.split('/')[0].toLowerCase();
  
  // Map model names to logo keys
  const logoMap: Record<string, string> = {
    'openai': 'openai',
    'anthropic': 'claude',
    'google': 'gemini',
    'meta-llama': 'meta',
    'meta': 'meta',
    'deepseek': 'deepseek',
    'qwen': 'qwen',
    'mistralai': 'mistral',
    'mistral': 'mistral',
    'x-ai': 'xai',
    'xai': 'xai',
    'cohere': 'cohere',
    'perplexity': 'perplexity',
  };
  
  const logoKey = logoMap[provider] || 'gemini'; // Default to gemini
  return LOGOS.models[logoKey as keyof typeof LOGOS.models] || '';
}
